360  /* 15.3.1.3.40 */
   361  /*
   362   *  call-seq:
   363   *     raise
   364   *     raise(string)
   365   *     raise(exception [, string])
   366   *
   367   *  With no arguments, raises a <code>RuntimeError</code>
   368   *  With a single +String+ argument, raises a
   369   *  +RuntimeError+ with the string as a message. Otherwise,
   370   *  the first parameter should be the name of an +Exception+
   371   *  class (or an object that returns an +Exception+ object when sent
   372   *  an +exception+ message). The optional second parameter sets the
   373   *  message associated with the exception, and the third parameter is an
   374   *  array of callback information. Exceptions are caught by the
   375   *  +rescue+ clause of <code>begin...end</code> blocks.
   376   *
   377   *     raise "Failed to create socket"
   378   *     raise ArgumentError, "No parameters", caller
   379   */
   380  MRB_API mrb_value
   381  mrb_f_raise(mrb_state *mrb, mrb_value self)
   382  {
   383    mrb_value exc, mesg;
   384    mrb_int argc;
   385
   386    argc = mrb_get_args(mrb, "|oo", &exc, &mesg);
   387    mrb->c->ci->mid = 0;
   388    switch (argc) {
   389    case 0:
   390      mrb_raise(mrb, E_RUNTIME_ERROR, "");
   391      break;
   392    case 1:
   393      if (mrb_string_p(exc)) {
   394        mesg = exc;
   395        exc = mrb_obj_value(E_RUNTIME_ERROR);
   396      }
   397      else {
   398        mesg = mrb_nil_value();
   399      }
   400      /* fall through */
   401    default:
   402      exc = mrb_make_exception(mrb, exc, mesg);
   403      mrb_exc_raise(mrb, exc);
   404      break;
   405    }
   406    return mrb_nil_value();            /* not reached */
   407  }
   408
   409  /* 15.3.1.3.41 */
   410  /*
   450    mrb_value str;
   451
   452    va_start(ap, fmt);
   453    str = mrb_vformat(mrb, fmt, ap);
   454    fputs("bug: ", stderr);
   455    fwrite(RSTRING_PTR(str), RSTRING_LEN(str), 1, stderr);
   456    va_end(ap);
   457  #endif
   458    exit(EXIT_FAILURE);
   459  }
