   507  MRB_API mrb_noreturn void
   508  mrb_no_method_error(mrb_state *mrb, mrb_sym id, mrb_value args, char const* fmt, ...)
   509  {
   510    va_list ap;
   511    mrb_value exc;
   512
   513    va_start(ap, fmt);
   514    exc = error_va(mrb, E_NOMETHOD_ERROR, fmt, ap);
   515    va_end(ap);
   516    mrb_iv_set(mrb, exc, MRB_IVSYM(name), mrb_symbol_value(id));
   517    mrb_iv_set(mrb, exc, MRB_IVSYM(args), args);
   518    mrb_exc_raise(mrb, exc);
   519  }
